/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/

void vin_init (void)           
{       
  if(!vin_init_nvfs())
    {
      // if error?
    }
    
  vin_info.vin.is_valid = !!vin_validate(vin_info.vin.code) ;  
  
  if(vin_info.vin.is_valid)
    {
      cmd_q_insert(INPUT_VIN_IS_DONE , COMMAND_INSERT_TIMEOUT) ; 
    }
  
  #if DBG_VIN == 1
    if(vin_info.vin.is_valid)
    {
      dbg_tx_text ("\nVin Is Valid") ;
    }
    else
    {
      dbg_tx_text ("\nVin Is Not Valid") ;
    }
        
  #endif  

}


